<script lang="ts">
 import {uploadTo} from './api';
 let {indent,onsave}:{indent:number;onsave:(rows:any[])=>void}=$props();
 let busy=$state(false),error=$state(''),data:any=$state(null),sheet=$state(0),first=$state(2),last=$state(20),point=$state(0),required=$state(1),unit=$state('cm');
 let rows=$derived(data?.sheets[sheet]?.rows||[]);
 let columns=$derived(Array.from({length:Math.max(1,...rows.map((r:string[])=>r.length))},(_,i)=>i));
 let preview=$derived(rows.slice(Math.max(0,first-1),last).filter((r:string[])=>r[point]?.trim()&&r[required]?.trim()).map((r:string[])=>({point:r[point].trim(),required:r[required].trim(),actual:'',unit,tolerance:'',remarks:''})));
 async function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file||busy)return;busy=true;error='';try{data=await uploadTo('/sample-indents/'+indent+'/spec-import',file);sheet=0;first=2;last=Math.min(101,data.sheets[0]?.rows.length||0)}catch(e){error=(e as Error).message}finally{busy=false;input.value=''}}
 function apply(){error='';if(!preview.length||preview.length>100){error='Select between 1 and 100 measurement rows.';return}if(point===required){error='Choose separate measurement and required-value columns.';return}if(preview.some((r:any)=>!Number.isFinite(Number(r.required))||Number(r.required)<0||Number(r.required)>10000||r.point.length>150)){error='Some required values are not plain numbers. Adjust the row range or columns, or enter those measurements manually.';return}onsave(preview);data=null}
</script>
<details class="import"><summary>Import buyer measurements from Excel, CSV or PDF</summary><p>Choose the required-value column for this garment’s size. Imported values remain editable; actual measurements must be entered by QA. Scanned PDFs need manual entry or the original spreadsheet.</p><label>Specification file (5 MB maximum)<input type="file" accept=".xlsx,.csv,.pdf" disabled={busy} onchange={upload}/></label>{#if busy}<p role="status">Reading specification…</p>{/if}{#if error}<p class="form-error" role="alert">{error}</p>{/if}
{#if data}<div class="mapping"><label>Worksheet<select bind:value={sheet} onchange={()=>{first=2;last=Math.min(101,rows.length)}}>{#each data.sheets as s,i}<option value={i}>{s.name}</option>{/each}</select></label><label>First measurement row<input type="number" min="1" max={rows.length} bind:value={first}/></label><label>Last measurement row<input type="number" min={first} max={rows.length} bind:value={last}/></label><label>Measurement-point column<select bind:value={point}>{#each columns as i}<option value={i}>Column {i+1} · {rows[0]?.[i]||''}</option>{/each}</select></label><label>Required value / size column<select bind:value={required}>{#each columns as i}<option value={i}>Column {i+1} · {rows[0]?.[i]||''}</option>{/each}</select></label><label>Measurement unit<select bind:value={unit}><option>cm</option><option>mm</option><option>in</option></select></label></div><p>{data.note}</p><div class="sheet"><table><thead><tr><th>Row</th>{#each columns as i}<th>Column {i+1}</th>{/each}</tr></thead><tbody>{#each rows as row,i}<tr class:selected={i+1>=first&&i+1<=last}><th>{i+1}</th>{#each columns as c}<td>{row[c]||''}</td>{/each}</tr>{/each}</tbody></table></div><p>{preview.length} measurement rows selected. Applying replaces the unsaved measurement rows in this audit.</p><button class="button primary" onclick={apply}>Use these measurements</button><button class="button secondary" onclick={()=>data=null}>Cancel import</button>{/if}</details>
<style>.import{border:1px solid #b7c9d2;padding:16px;border-radius:10px;margin:18px 0;background:#fff}summary{font-weight:700;cursor:pointer}p{line-height:1.5}label{display:grid;gap:7px;font-weight:700}.mapping{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}input,select{min-width:0;width:100%;padding:9px;background:#eff5fa;color:#101820;border:1px solid #adc1cc;border-radius:6px}.sheet{max-height:280px;overflow:auto}table{border-collapse:collapse;font-size:13px}th,td{border:1px solid #c4d3dc;padding:7px;min-width:100px}tr.selected{background:#e5f3ed}button{margin:6px 8px 0 0}@media(max-width:650px){.mapping{grid-template-columns:1fr}}</style>
